WITH base AS (SELECT *, CONCAT_WS('-', merchant, txn_type) merchant_txn_type_key, CONCAT(merchant, ' ', txn_type) merchant_txn_type, COALESCE(merchant, 'OTHER') resolved_merchant FROM transactions WHERE txn_time > DATE '2023-09-28'), flagged AS (SELECT *, CASE WHEN LAG(txn_time) OVER (PARTITION BY account_id ORDER BY txn_time, id) IS NULL OR txn_time > LAG(txn_time) OVER (PARTITION BY account_id ORDER BY txn_time, id) + INTERVAL 14 DAYS THEN 1 ELSE 0 END AS session_start_flag FROM base), sessionized AS (SELECT id, account_id, txn_type, txn_time, merchant, is_flagged, SUM(session_start_flag) OVER (PARTITION BY account_id ORDER BY txn_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_no FROM flagged) SELECT CASE WHEN session_no >= 6 THEN 'HIGH' ELSE 'LOW' END AS session_no_tier, session_no, (UNIX_TIMESTAMP(MAX(txn_time)) - UNIX_TIMESTAMP(MIN(txn_time))) / 60 AS duration_min, COUNT_IF(txn_type = 'FEE') AS fee_events, MAX(session_no) AS max_session_no, SUM(CASE WHEN txn_type = 'FEE' THEN session_no ELSE 0 END) AS fee_session_no, SORT_ARRAY(COLLECT_SET(merchant)) AS merchant_list FROM sessionized GROUP BY GROUPING SETS ((CASE WHEN session_no >= 6 THEN 'HIGH' ELSE 'LOW' END, session_no), (CASE WHEN session_no >= 6 THEN 'HIGH' ELSE 'LOW' END), ()) ORDER BY session_no_tier DESC NULLS FIRST;
